// Copies the compiled ABIs from contracts/out into src/lib/abi.ts.
import { readFileSync, writeFileSync } from "node:fs";
const read = (p) => JSON.parse(readFileSync(new URL(p, import.meta.url))).abi;
const escrow = read("../../contracts/out/ZillaEscrow.sol/ZillaEscrow.json");
const token = read("../../contracts/out/MockStablecoin.sol/MockStablecoin.json");
const body =
  "// Generated by scripts/export-abi.mjs from contracts/out. Do not edit by hand.\n" +
  `export const escrowAbi = ${JSON.stringify(escrow, null, 2)} as const;\n\n` +
  `export const tokenAbi = ${JSON.stringify(token, null, 2)} as const;\n`;
writeFileSync(new URL("../src/lib/abi.ts", import.meta.url), body);
console.log("wrote src/lib/abi.ts");
